    <script>
        const crops = [
            { id: 'wheat', name: 'ઘઉં · Wheat', season: 'rabi', seasonLabel: 'Rabi crop', image: 'https://images.unsplash.com/photo-1632913227227-23798668226d?auto=format&fit=crop&w=1200&q=85', intro: 'ઠંડી ઋતુમાં ઉગતો મુખ્ય અનાજ પાક.', sowing: 'નવેમ્બરનો પ્રથમ પખવાડિયો સૌથી શ્રેષ્ઠ સમય છે. બીજને પાયાના ખાતર સાથે 3 થી 4 સેમી ઊંડાઈએ વાવો.', soil: 'સારી નિતારવાળી ગોરાડુ અને મધ્યમ કાળી માટી વધુ અનુકૂળ છે. માટીનું pH 6.0 થી 7.5 હોવું જોઈએ.', fertilizer: 'વાવણી સમયે હેક્ટરે 50 કિલો નાઇટ્રોજન અને 50 કિલો ફોસ્ફરસ પાયાના ખાતરમાં આપો. ત્યારબાદ ટિલરિંગ અવસ્થામાં વધારાનું નાઇટ્રોજન આપો.', water: 'વાવણી પછી તુરંત પિયત આપો. ત્યારબાદ ક્રાઉન રૂટ (21 દિવસ), ટિલરિંગ, ફૂલ અને દાણા ભરાવા સમયે પિયત અતિ આવશ્યક છે.', pest: 'માહુ (Aphid) અને ગેરુ (Rust) નો ઉપદ્રવ જોવા મળે છે. અઠવાડિક નિરીક્ષણ કરો અને રોગગ્રસ્ત ભાગ કાઢી નાખો. જો ઉપદ્રવ વધુ હોય તો જંતુનાશક દવા છાંટો.' },
            
            { id: 'cotton', name: 'કપાસ · Cotton', season: 'kharif', seasonLabel: 'Kharif crop', image: 'https://images.unsplash.com/photo-1664956491340-2e9f5e51cd28?auto=format&fit=crop&w=1200&q=85', intro: 'ગરમ હવામાનમાં લાંબી અવધિનો રોકડ પાક.', sowing: 'જૂન–જુલાઈ મહિનામાં સારો વરસાદ થયા પછી વાવણી કરો. હાઇબ્રિડ જાતોમાં છોડ વચ્ચે 90x60 સેમી અંતર રાખો.', soil: 'ઊંડી કાળી અથવા મધ્યમ નિતારવાળી ગોરાડુ માટી સારી રહે છે. ખેતરમાં પાણી ભરાવું ન જોઈએ.', fertilizer: 'માટી પરીક્ષણ (Soil-test) મુજબ NPK આપો. નાઇટ્રોજનને 3 કે 4 ભાગમાં વહેંચીને આપવાથી છોડનો વિકાસ સારો થાય છે.', water: 'છોડના વિકાસ, ફૂલ આવવાના સમયે અને જીંડવા (boll) બનવાના સમયે ભેજ જાળવવો જરૂરી છે. વધારે વરસાદમાં પાણીનો નિકાલ કરો.', pest: 'સફેદમાખી, તડતડીયા અને ગુલાબી ઈયળ મુખ્ય જીવાત છે. ખેતરમાં પીળા અને ફેરોમોન ટ્રેપ્સ ગોઠવો. નિષ્ણાતની સલાહથી દવાનો છંટકાવ કરો.' },
            
            { id: 'groundnut', name: 'મગફળી · Groundnut', season: 'kharif', seasonLabel: 'Kharif crop', image: 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Arachis_hypogaea_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-163.jpg/500px-Arachis_hypogaea_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-163.jpg', intro: 'હલકી નિતારવાળી માટીમાં સારી રીતે થતો તેલબિયાં પાક.', sowing: 'ચોમાસામાં જૂન–જુલાઈ અથવા સિંચાઈવાળા વિસ્તારમાં ઉનાળુ પાક તરીકે ફેબ્રુઆરીમાં વાવો. બીજને ફૂગનાશકનો પટ આપવો જરૂરી છે.', soil: 'હલકી ગોરાડુ, રેતાળ અને નિતારવાળી માટી મગફળીના મૂળ અને ડોડવા (Peg) ના વિકાસ માટે ઉત્તમ છે.', fertilizer: 'વાવણી પહેલાં સડી ગયેલું દેશી ખાતર નાખો. માટી પરીક્ષણ મુજબ ફોસ્ફરસ અને જીપ્સમ (કેલ્શિયમ) આપવાથી દાણા ભરાવદાર બને છે.', water: 'વાવણી સમયે, ફૂલ આવવા સમયે અને ડોડવા બેસવાના સમયે (Pegging) ભેજ ખૂબ જરૂરી છે. પાક તૈયાર થવાના સમયે સિંચાઈ બંધ કરવી.', pest: 'જેસિડ, થ્રિપ્સ, મુંડા (White grub) અને ટિક્કા રોગ મુખ્ય છે. પાકની ફેરબદલી કરો અને રોગ મુક્ત પ્રમાણિત બીજનો ઉપયોગ કરો.' },
            
            { id: 'cumin', name: 'જીરું · Cumin', season: 'rabi', seasonLabel: 'Rabi crop', image: 'https://upload.wikimedia.org/wikipedia/commons/5/58/Cuminum_cyminum_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-198.jpg', intro: 'સુકા અને ઠંડા હવામાનમાં ઉત્તમ મસાલા પાક.', sowing: 'નવેમ્બર મધ્યથી ડિસેમ્બરના પહેલા અઠવાડિયા સુધી. વધારે ભેજ ન હોય તેવા ઠંડા હવામાનમાં વાવેતર કરો.', soil: 'હલકી નિતારવાળી માટી વધુ અનુકૂળ છે. માટીમાં પાણી ભરાવાથી સૂકારો (Wilt) અને બ્લાઇટ રોગ વધે છે.', fertilizer: 'જૈવિક ખાતર વધુ વાપરો. ફોસ્ફરસ પાયામાં આપો અને નાઇટ્રોજન ખૂબ જ મર્યાદિત માત્રામાં વાપરો, વધુ નાઇટ્રોજન રોગ વધારે છે.', water: 'જીરુંને ઓછી સિંચાઈની જરૂર હોય છે. જમીનમાં પૂરતો ભેજ હોય ત્યારે જ હળવી સિંચાઈ આપો, પાણી ભરાવા ન દો.', pest: 'સૂકારો, ભૂકી છારો (Powdery mildew) અને કાલવ્રણ (Blight) સામાન્ય છે. સ્વચ્છ બીજ અને ટ્રાયકોડર્મા જમીનમાં વાપરો. રોગ દેખાય તો મંજૂર ફૂગનાશક વાપરો.' },
            
            { id: 'paddy', name: 'ડાંગર · Paddy', season: 'kharif', seasonLabel: 'Kharif crop', image: 'https://images.unsplash.com/photo-1677142714781-916e7faeef0b?auto=format&fit=crop&w=1200&q=85', intro: 'પાણી અને ભેજનું યોગ્ય સંચાલન માંગતો અનાજ પાક.', sowing: 'જૂન મહિનામાં નર્સરી તૈયાર કરો અને જુલાઈમાં વરસાદની સ્થિતિ મુજબ મુખ્ય ખેતરમાં રોપણી (Transplanting) કરો.', soil: 'પાણીને રોકી શકે તેવી ચીકણી કે દોળિયાળી માટી સૌથી વધુ અનુકૂળ છે. જમીનનું લેવલિંગ હોવું જરૂરી છે.', fertilizer: 'નાઇટ્રોજન ખાતરને 3 થી 4 ભાગમાં આપો. ફોસ્ફરસ અને પોટાશ રોપણી વખતે જમીનમાં ભેળવો. ઝીંકની ઉણપ માટે ઝીંક સલ્ફેટ આપો.', water: 'રોપણી પછી ખેતરમાં 2-3 સેમી પાણી જાળવી રાખો. ડાળી ફૂટવા અને દાણા ભરાવાના સમયે જમીન સૂકવી ન જોઈએ. કાપણીના 15 દિવસ પહેલાં પાણી બંધ કરો.', pest: 'સ્ટેમ બોરર (Stem borer), ગાભમારાની ઈયળ અને લીફ ફોલ્ડર. ખેતરમાં પ્રકાશ પિંજર (Light traps) ગોઠવો અને નિયમિત દેખરેખ રાખો.' },
            
            { id: 'tomato', name: 'ટામેટા · Tomato', season: 'vegetable', seasonLabel: 'Vegetable crop', image: 'https://images.unsplash.com/photo-1566218246241-934ad8b38ea6?auto=format&fit=crop&w=1200&q=85', intro: 'નિયંત્રિત સિંચાઈ અને સતત નિરીક્ષણથી સારી આવક આપતો શાકભાજી પાક.', sowing: 'ચોમાસા સિવાય શિયાળા કે ઉનાળાની શરૂઆતમાં નર્સરીમાં ધરુ ઉછેરીને રોપણી કરી શકાય છે. છોડ વચ્ચે 60x60 સેમી અંતર રાખો.', soil: 'સારી નિતારવાળી ભુરભુરી, ગોરાડુ માટીમાં સારું ઉત્પાદન મળે છે. મલ્ચિંગ (Mulching) નો ઉપયોગ કરવાથી ફાયદો થાય છે.', fertilizer: 'સડી ગયેલું છાણિયું ખાતર પાયામાં આપો. ફૂલ અને ફળધારણ સમયે પોટાશ ખાતર આપવાથી ફળની ગુણવત્તા સુધરે છે.', water: 'ટપક સિંચાઈ (Drip irrigation) સૌથી શ્રેષ્ઠ છે. પાણીમાં અચાનક મોટો વધારો કે ઘટાડો કરવાથી ફળ ફાટી શકે છે.', pest: 'ફળછેદક ઈયળ, સફેદમાખી અને અર્લી બ્લાઈટ (ફૂગ). ફેરોમોન ટ્રેપ્સ ગોઠવો. રોગિષ્ટ પાંદડા કે ફળ દેખાય તો તુરંત કાઢીને દૂર કરો.' },
            
            { id: 'maize', name: 'મકાઈ · Maize', season: 'kharif', seasonLabel: 'Kharif crop', image: 'https://images.unsplash.com/photo-1551754655-cd27e38d2076?auto=format&fit=crop&w=1200&q=85', intro: 'ઝડપી વૃદ્ધિ અને યોગ્ય ભેજથી સારો ચારો અને અનાજ પાક.', sowing: 'ચોમાસામાં જૂન–જુલાઈમાં વાવો અથવા સિંચાઈની સગવડ હોય તો જાન્યુઆરી–ફેબ્રુઆરીમાં શિયાળુ પાક તરીકે લઈ શકાય.', soil: 'સારી નિતારવાળી ગોરાડુ કે બેસર માટી વધુ યોગ્ય છે. જમીનમાં પાણી લાંબો સમય ભરાઈ રહેવું ન જોઈએ.', fertilizer: 'મકાઈ વધુ પોષક તત્વો માંગે છે. નાઇટ્રોજનને ત્રણ સરખા ભાગમાં આપો (વાવણી, ઘૂંટણની ઊંચાઈ અને ફૂલ સમયે).', water: 'વાવણી પછી, ઘૂંટણ ઊંચાઈએ પહોંચે ત્યારે અને દાણા ભરાતી વખતે ભેજ અતિ આવશ્યક છે.', pest: 'ફોલ આર્મીવોર્મ (Fall Armyworm) અને ગાભમારાની ઈયળ મુખ્ય જીવાત છે. પાંદડાની અંદર તપાસ કરો અને ફેરોમોન ટ્રેપ્સ વાપરો.' },
            
            { id: 'chickpea', name: 'ચણા · Chickpea', season: 'rabi', seasonLabel: 'Rabi crop', image: 'https://images.unsplash.com/photo-1518977676601-b53f82aba655?auto=format&fit=crop&w=1200&q=85', intro: 'ઓછા પાણીમાં ઉગતો મહત્વનો શિયાળુ કઠોળ પાક.', sowing: 'ઓક્ટોબરના અંતથી નવેમ્બરના મધ્ય સુધી વાવણી કરવી જોઈએ. બીજને ફૂગનાશકનો પટ આપીને વાવો.', soil: 'મધ્યમથી કાળી અને સારી ભેજસંગ્રહ શક્તિ ધરાવતી માટી યોગ્ય છે. નિતાર વ્યવસ્થા સારી હોવી જોઈએ.', fertilizer: 'ચણા કઠોળ હોવાથી હવામાંથી નાઇટ્રોજન લે છે. વાવેતર સમયે બીજને રાઇઝોબિયમ કલ્ચર (Rhizobium) નો પટ આપો.', water: 'ચણાને માત્ર 1 કે 2 હળવી સિંચાઈની જરૂર હોય છે. ફૂલ બેસવાના સમયે અને પોપટા (Pod) બેસવાના સમયે સિંચાઈ આપવી મહત્વપૂર્ણ છે.', pest: 'પોપટા કોરી ખાનાર ઈયળ (Pod borer). ફેરોમોન ટ્રેપ્સ લગાવો, પક્ષીઓ બેસવા માટે ટી-આકારના લાકડા (Bird perches) ખેતરમાં ગોઠવો.' },
            
            { id: 'pigeonpea', name: 'તૂવેર · Pigeon Pea', season: 'kharif', seasonLabel: 'Kharif crop', image: 'https://images.unsplash.com/photo-1627471904797-4d92bd121c22?auto=format&fit=crop&w=1200&q=85', intro: 'ગુજરાતનો મુખ્ય કઠોળ પાક, જે લાંબા ગાળાનો છે.', sowing: 'જૂન થી જુલાઈ માસમાં. કપાસ કે મગફળી સાથે આંતરપાક તરીકે પણ વાવી શકાય.', soil: 'ભારે કાળીથી લઈને મધ્યમ અને સારી નિતારવાળી જમીન. વધુ પડતું પાણી નુકસાન કરે છે.', fertilizer: 'હવામાંથી નાઇટ્રોજન લેતો હોવાથી નાઇટ્રોજનની ઓછી જરૂર છે. પાયામાં ફોસ્ફરસ આપો.', water: 'ફૂલ અને શિંગો બેસવાના સમયે પાણી આપવું ખૂબ જરૂરી છે. દુષ્કાળ પ્રતિકારક પાક છે.', pest: 'ફળી કોરી ખાનાર ઈયળ (Pod borer). લીંબોળીનું તેલ (Neem oil) અને ફેરોમોન ટ્રેપ વાપરો.' },
            
            { id: 'greengram', name: 'મગ · Green Gram', season: 'kharif', seasonLabel: 'Kharif crop', image: 'https://images.unsplash.com/photo-1594957640243-7f28df661cf6?auto=format&fit=crop&w=1200&q=85', intro: 'ટૂંકા ગાળાનો અને જમીન ફળદ્રુપ બનાવતો કઠોળ પાક.', sowing: 'ચોમાસાની શરૂઆતમાં (જૂન-જુલાઈ) અથવા ઉનાળુ પાક તરીકે માર્ચમાં.', soil: 'ગોરાડુ અને સારી નિતારવાળી જમીન ઉત્તમ છે. ક્ષારવાળી જમીન માફક આવતી નથી.', fertilizer: 'ખૂબ ઓછું ખાતર જોઈએ. રાઇઝોબિયમ કલ્ચરનો પટ આપીને વાવણી કરો.', water: 'ઉનાળુ મગમાં 3-4 પિયતની જરૂર પડે છે. ફૂલ અને શિંગોના વિકાસ વખતે પિયત અગત્યનું છે.', pest: 'મોલોમશી, થ્રિપ્સ અને સફેદ માખી. યોગ્ય સમયે જંતુનાશક અને પીળા ટ્રેપ્સ વાપરો.' },
            
            { id: 'onion', name: 'ડુંગળી · Onion', season: 'rabi', seasonLabel: 'Rabi crop', image: 'https://images.unsplash.com/photo-1625904835711-02be3b207ed4?auto=format&fit=crop&w=1200&q=85', intro: 'વ્યાપારી ધોરણે લેવાતો અગત્યનો કંદમૂળ પાક.', sowing: 'ઓક્ટોબર-નવેમ્બરમાં ધરૂવાડિયું (Nursery) તૈયાર કરી ડિસેમ્બરમાં રોપણી કરવી.', soil: 'ચીકણી નહીં પરંતુ નિતારવાળી, ગોરાડુ અને સેન્દ્રીય તત્વો ધરાવતી જમીન ખૂબ અનુકૂળ છે.', fertilizer: 'છાણિયું ખાતર વધુ નાખો. નાઇટ્રોજન, ફોસ્ફરસ અને પોટાશની પૂરતી માત્રા કંદના વિકાસ માટે જરૂરી છે.', water: 'રોપણી પછી હળવું પિયત આપો. કંદના વિકાસ સમયે પિયત ચૂકવું નહીં. કાપણીના 15 દિવસ પહેલા પિયત બંધ કરો.', pest: 'થ્રિપ્સ અને જાંબલી ધાબાનો રોગ (Purple blotch). પ્રોપર ફૂગનાશક અને કીટનાશક છાંટો.' },
            
            { id: 'potato', name: 'બટાટા · Potato', season: 'rabi', seasonLabel: 'Rabi crop', image: 'https://images.unsplash.com/photo-1518977822534-7049a61ee0c2?auto=format&fit=crop&w=1200&q=85', intro: 'ટૂંકા ગાળામાં સૌથી વધુ ઉત્પાદન આપતો શાકભાજી પાક.', sowing: 'નવેમ્બર માસમાં ઠંડી શરૂ થતાં વાવેતર કરો. રોગમુક્ત સર્ટિફાઇડ બીજનો (Tuber) જ ઉપયોગ કરો.', soil: 'ભુરભુરી, રેતાળ-ગોરાડુ જમીન કંદના વિકાસ માટે ઉત્તમ છે.', fertilizer: 'પાયાના ખાતરમાં છાણિયું ખાતર અને પોટાશ અગત્યના છે. નાઇટ્રોજનને બે હપ્તામાં આપો.', water: 'ટપક સિંચાઈથી ઉત્તમ રિઝલ્ટ મળે છે. જમીનમાં સતત ભેજ જળવાવો જોઈએ પણ પાણી ભરાવું ન જોઈએ.', pest: 'અર્લી અને લેટ બ્લાઇટ (Early & Late Blight) અને મોલોમશી. હવામાન મુજબ આગોતરી ફૂગનાશક દવાનો છંટકાવ કરો.' },

            { id: 'brinjal', name: 'રીંગણ · Brinjal', season: 'vegetable', seasonLabel: 'Vegetable crop', image: 'https://images.unsplash.com/photo-1591121175658-b198b18f509e?auto=format&fit=crop&w=1200&q=85', intro: 'વર્ષ દરમિયાન લેવાતો સૌથી લોકપ્રિય શાકભાજી પાક.', sowing: 'ધરૂ તૈયાર કરીને જૂન-જુલાઈ (ચોમાસુ) અથવા ઓક્ટોબર-નવેમ્બર (શિયાળુ) માં રોપણી કરી શકાય.', soil: 'લગભગ તમામ પ્રકારની નિતારવાળી જમીનમાં થાય છે, ગોરાડુ માટી શ્રેષ્ઠ છે.', fertilizer: 'ફૂલ અને ફળ સતત આવતા હોવાથી સમયાંતરે નાઇટ્રોજન આપતા રહેવું જરૂરી છે.', water: 'શિયાળામાં 10-12 દિવસે અને ઉનાળામાં 5-7 દિવસે પિયત આપો.', pest: 'ડૂંખ અને ફળ કોરી ખાનાર ઈયળ (Shoot & Fruit Borer). નુકસાનગ્રસ્ત ભાગો તોડી નાશ કરો અને યોગ્ય દવા છાંટો.' }
        ];
        const grid = document.getElementById('cropGrid'); const detailImage = document.getElementById('detailImage'); let selected = 'wheat';
    function renderCards() { const query = document.getElementById('search').value.toLowerCase().trim(); const category = document.getElementById('category').value; const results = crops.filter(crop => crop.name.toLowerCase().includes(query) && (category === 'all' || crop.season === category)); grid.innerHTML = results.map(crop => `<article class="crop-card ${crop.id === selected ? 'selected' : ''}" data-id="${crop.id}"><img class="crop-image" src="${crop.image}" alt="${crop.name}"><div class="crop-card-body"><h3>${crop.name}</h3><p>${crop.intro}</p><span class="chip">${crop.seasonLabel}</span></div></article>`).join('') || '<div class="no-results" style="display:block">No crop found. Try another search.</div>'; grid.querySelectorAll('.crop-card').forEach(card => card.addEventListener('click', () => { selected = card.dataset.id; updateDetail(); renderCards(); document.getElementById('detailPanel').scrollIntoView({ behavior: 'smooth', block: 'center' }); })); }
    function updateDetail() { const crop = crops.find(item => item.id === selected); detailImage.style.backgroundImage = `url('${crop.image}')`; document.getElementById('detailKicker').textContent = crop.seasonLabel; document.getElementById('detailName').textContent = crop.name; document.getElementById('detailIntro').textContent = crop.intro; document.getElementById('detailSowing').textContent = crop.sowing; document.getElementById('detailSoil').textContent = crop.soil; document.getElementById('detailFertilizer').textContent = crop.fertilizer; document.getElementById('detailWater').textContent = crop.water; document.getElementById('detailPest').textContent = crop.pest; }
    document.getElementById('search').addEventListener('input', renderCards); document.getElementById('category').addEventListener('change', renderCards); updateDetail(); renderCards();
    </script>
</body>
</html>
